**HTML**

```html
<!DOCTYPE html>
<html>
<head>
  <title>Image Categorizer</title>
  <style>
    body { margin: 0; padding: 0; }
    #container { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; }
    .image { width: 250px; height: 250px; margin: 10px; }
    .category { font-size: 24px; margin: 10px; color: #333; }
  </style>
</head>
<body>

<h1>Image Categorizer</h1>

<div id="container">

  <div class="image" data-category="category1">Image 1</div>
  <div class="image" data-category="category2">Image 2</div>
  <div class="image" data-category="category3">Image 3</div>
  <div class="image" data-category="category4">Image 4</div>

</div>

<script>
  const images = document.querySelectorAll('.image');
  const categories = document.querySelectorAll('.category');

  images.forEach(image => {
    image.addEventListener('click', function() {
      const category = image.getAttribute('data-category');
      const filteredImages = images.filter(image => image.getAttribute('data-category') === category);

      // Swap images in the container
      document.getElementById('container').innerHTML = '';
      filteredImages.forEach(image => image.style.display = 'flex');
    });
  });
</script>

</body>
</html>
```

**JavaScript**

```javascript
const images = document.querySelectorAll('.image');
const categories = document.querySelectorAll('.category');

images.forEach(image => {
  image.addEventListener('click', function() {
    const category = image.getAttribute('data-category');

    // Filter images based on category
    const filteredImages = images.filter(image => image.getAttribute('data-category') === category);

    // Swap images in the container
    document.getElementById('container').innerHTML = '';
    filteredImages.forEach(image => image.style.display = 'flex');
  });
});
```

**How it works**

1. The HTML contains a container element with flexbox layout.
2. Each image has a data attribute named `data-category` that stores the category of the image.
3. The JavaScript iterates over all images and adds a click event listener to each image.
4. When an image is clicked, it gets the category from its `data-category` attribute.
5. It then filters the images using `querySelectorAll` with the same category and swaps them in the container.
6. The container is cleared and the filtered images are displayed in a flexbox layout.

**Note**

* You can customize the number of columns and spacing between images by adjusting the flex-wrap property in the CSS.
* You can add a counter or indicator to each category to show the number of images in that category.

```javascript
function characterCounter(str) {
  // Create an object to store the character counts
  const counts = {};

  // Split the string into an array of characters
  const chars = str.split('');

  // For each character in the string
  for (const char of chars) {
    // If the character is a letter, add it to the counts object
    if (char.toLowerCase() === char) {
      counts[char] = (counts[char] || 0) + 1;
    }
  }

  // Return the counts object
  return counts;
}

// Example usage:
const str = 'hello world';
const counts = characterCounter(str);

// Print the character counts
console.log(counts);
```

