import random

class Animal:
    def __init__(self, name, habitat):
        self.name = name
        self.habitat = habitat
        self.food_type = "herbivore"

    def eat(self):
        # Simulate the animal eating from the habitat
        if self.food_type == "herbivore":
            self.food = random.choice(self.habitat.plants)
        else:
            self.food = random.choice(self.habitat.animals)

    def reproduce(self):
        # Simulate the animal reproducing
        if random.random() < 0.05:
            new_animal = Animal(self.name + " Jr.", self.habitat)
            return new_animal
        return None

    def display(self):
        print(f"{self.name} is a {self.habitat} animal.")

# Create an animal
animal = Animal("Fox", {"forest": True, "grassland": False})

# Keep the animal alive until it reproduces
while True:
    animal.eat()
    if animal.reproduce():
        animal = animal.reproduce()
    else:
        break

# Print the animal's information
animal.display()
```

